urlset:
{{ site.url }}/
{%- assign search_page = site.pages | where: "url", "/search/" | first %}
{%- if search_page %}{{ site.url }}/search/{% endif %}
{%- assign slugs = "" | split: "" %}
{%- for doc in site.data.registry_catalog.items %}
  {%- if doc.display_category_slug %}{% assign slugs = slugs | push: doc.display_category_slug %}{% endif %}
{%- endfor %}
{%- assign slugs = slugs | uniq %}
{%- for slug in slugs %}
{{ site.url }}/{{ slug }}/
{%- endfor %}
{%- for doc in site.data.registry_catalog.items %}
{{ site.url }}{{ doc.url }}{% if doc.date %}{{ doc.date }}{% endif %}
{%- endfor %}
